import { afterEach, describe, expect, it, vi } from 'vitest'
const native = vi.hoisted(() => ({ invoke: vi.fn() }))
vi.mock('@tauri-apps/api/core', () => ({ invoke: native.invoke, Channel: class { onmessage = (_value: unknown) => {} } }))
import { beginExternalProgress, clearExternalProgress, externalJobFraction, externalProgressFor, subscribeExternalProgress, type ExternalOperationProgress, type ExternalTransferSnapshot } from './progress'
import type { ExternalJobSummary } from './types'
const reading = (sequence: number, uploadedBytes: string): ExternalTransferSnapshot => ({ sequence, stage: 'uploading', uploadedBytes, preparedBytes: '0', downloadedBytes: '0', uploadedObjects: '1', downloadedObjects: '0' })
afterEach(() => { for (const id of ['a', 'b']) clearExternalProgress(id); vi.useRealTimers(); native.invoke.mockReset() })
describe('external progress ownership', () => {
    it('keeps body throughput separate from confirmed amounts and rejects samples from replaced operations', async () => {
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        const run = beginExternalProgress('a', 'download')
        run.items(0, 3)
        const channel = run.networkChannel()
        const network = { id: 'native', atMs: 1000, sentBytes: '0', receivedBytes: '2000', sending: false, receiving: true }
        channel.onmessage({ ...reading(2, '999'), network })
        expect(externalProgressFor(state, 'a', 'download')).toMatchObject({ stage: 'downloading', completedItems: 0, amounts: { uploadedBytes: '0', downloadedBytes: '0' }, network })
        channel.onmessage({ ...reading(1, '0'), network: { ...network, receivedBytes: '9000' } })
        channel.onmessage({ ...reading(3, '0'), network: { ...network, receivedBytes: 'invalid' } })
        expect(externalProgressFor(state, 'a', 'download')?.network?.receivedBytes).toBe('2000')
        const retry = beginExternalProgress('a', 'download')
        channel.onmessage({ ...reading(4, '0'), network })
        expect(externalProgressFor(state, 'a', 'download')?.network).toBeUndefined()
        retry.finish('complete'); stop()
    })
    it('does not let delayed native speed replace a newer native page or local phase', async () => {
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        native.invoke.mockResolvedValue(undefined)
        const run = beginExternalProgress('a', 'binding')
        await run.invoke('first', {})
        const first = native.invoke.mock.calls[0][1].progress
        await run.invoke('second', {})
        const second = native.invoke.mock.calls[1][1].progress
        const network = { id: 'second', atMs: 1000, sentBytes: '2000', receivedBytes: '0', sending: true, receiving: false }
        second.onmessage({ ...reading(1, '0'), uploadedObjects: '0', network })
        first.onmessage({ ...reading(1, '0'), network: { ...network, id: 'first', sentBytes: '9999' } })
        expect(externalProgressFor(state, 'a')?.network).toEqual(network)
        run.stage('applying')
        second.onmessage({ ...reading(2, '100'), network: { ...network, sentBytes: '9999' } })
        expect(externalProgressFor(state, 'a')).toMatchObject({ stage: 'applying', network, amounts: { uploadedBytes: '100' } })
        run.finish('complete'); stop()
    })
    it('isolates connections and operations, ignores old sequences, and retains the result for remounts', async () => {
        vi.useFakeTimers()
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        let finish!: () => void
        native.invoke.mockImplementation(() => new Promise<void>(resolve => finish = resolve))
        const a = beginExternalProgress('a', 'binding')
        const run = a.invoke('synthetic', {}, '4')
        const channel = native.invoke.mock.calls[0][1].progress
        channel.onmessage(reading(2, '100'))
        channel.onmessage(reading(1, '999'))
        const b = beginExternalProgress('b', 'download')
        b.items(2, 8)
        expect(externalProgressFor(state, 'a')?.amounts.uploadedBytes).toBe('100')
        expect(externalProgressFor(state, 'b', 'download')?.completedItems).toBe(2)
        finish(); await run
        a.stage('applying', '5')
        channel.onmessage(reading(3, '500'))
        expect(externalProgressFor(state, 'a')).toMatchObject({ stage: 'applying', authority: '5', state: 'running' })
        expect(externalProgressFor(state, 'a')?.amounts.uploadedBytes).toBe('100')
        stop()
        a.finish('complete')
        const remount = subscribeExternalProgress(value => state = value)
        expect(externalProgressFor(state, 'a')?.state).toBe('complete')
        b.finish('cancelled'); remount()
    })
    it('a new attempt cannot be overwritten or cleared by a previous attempt', async () => {
        vi.useFakeTimers()
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        const old = beginExternalProgress('a', 'binding')
        old.finish('complete')
        const retry = beginExternalProgress('a', 'binding')
        retry.stage('downloading')
        old.finish('failed')
        await vi.advanceTimersByTimeAsync(4000)
        expect(externalProgressFor(state, 'a')).toMatchObject({ state: 'running', stage: 'downloading' })
        retry.finish('failed'); stop()
    })
    it('does not flash a no-change check and does not let routine work replace binding progress', async () => {
        vi.useFakeTimers()
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        const routine = beginExternalProgress('a', 'sync')
        routine.stage('preparing')
        await vi.advanceTimersByTimeAsync(60_000)
        expect(externalProgressFor(state, 'a')).toBeUndefined()
        routine.finish('complete', false)
        expect(externalProgressFor(state, 'a')).toBeUndefined()
        const binding = beginExternalProgress('a', 'binding')
        binding.stage('applying')
        const next = beginExternalProgress('a', 'sync')
        await vi.advanceTimersByTimeAsync(700)
        expect(externalProgressFor(state, 'a')?.stage).toBe('applying')
        binding.finish('complete'); next.finish('complete', false); stop()
    })
    it('accumulates bounded native pages without treating their totals as a whole-operation percentage', async () => {
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        native.invoke.mockImplementation(async (_command, { progress }) => progress.onmessage(reading(1, '50')))
        const run = beginExternalProgress('a', 'binding')
        await run.invoke('first', {}); await run.invoke('second', {})
        expect(externalProgressFor(state, 'a')?.amounts.uploadedBytes).toBe('100')
        run.finish('complete'); stop()
    })
    it.each(['failed', 'cancelled'] as const)('expires a %s result without clearing a new attempt', async stateName => {
        vi.useFakeTimers()
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        const run = beginExternalProgress('a', 'export')
        run.finish(stateName)
        expect(externalProgressFor(state, 'a', 'export')?.state).toBe(stateName)
        await vi.advanceTimersByTimeAsync(4000)
        expect(externalProgressFor(state, 'a', 'export')).toBeUndefined()
        const old = beginExternalProgress('a', 'binding')
        old.finish(stateName)
        const retry = beginExternalProgress('a', 'binding')
        await vi.advanceTimersByTimeAsync(4000)
        expect(externalProgressFor(state, 'a')?.id).toBeDefined()
        expect(externalProgressFor(state, 'a')?.state).toBe('running')
        retry.finish('complete'); stop()
    })
    it('accepts late final counters across native replies without reverting the stage or duplicating totals', async () => {
        vi.useFakeTimers()
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        native.invoke.mockResolvedValue(undefined)
        const run = beginExternalProgress('a', 'binding')
        await run.invoke('first', {}, '4')
        const first = native.invoke.mock.calls[0][1].progress
        run.stage('applying')
        first.onmessage(reading(1, '50'))
        expect(externalProgressFor(state, 'a')).toMatchObject({ stage: 'applying', amounts: { uploadedBytes: '50' } })
        await run.invoke('second', {}, '4')
        const second = native.invoke.mock.calls[1][1].progress
        second.onmessage(reading(1, '30'))
        run.finish('complete')
        first.onmessage(reading(2, '70'))
        second.onmessage(reading(2, '40'))
        second.onmessage(reading(1, '900'))
        expect(externalProgressFor(state, 'a')).toMatchObject({ state: 'complete', amounts: { uploadedBytes: '110' } })
        await vi.advanceTimersByTimeAsync(4000)
        second.onmessage(reading(3, '50'))
        expect(externalProgressFor(state, 'a')).toBeUndefined()
        stop()
    })
    it('reveals real work immediately and keeps uploading while preparation overlaps', async () => {
        let state: ReadonlyMap<string, ExternalOperationProgress> = new Map()
        const stop = subscribeExternalProgress(value => state = value)
        native.invoke.mockImplementation(async (_command, { progress }) => {
            progress.onmessage({ ...reading(1, '0'), uploadedObjects: '0' })
            progress.onmessage({ ...reading(2, '0'), uploadedObjects: '0', stage: 'preparing', preparedBytes: '100' })
            expect(externalProgressFor(state, 'a')?.stage).toBe('uploading')
            progress.onmessage({ ...reading(3, '50'), preparedBytes: '100' })
            progress.onmessage({ ...reading(4, '50'), stage: 'preparing', preparedBytes: '100' })
        })
        const run = beginExternalProgress('a', 'sync')
        await run.invoke('upload', {})
        expect(externalProgressFor(state, 'a')).toMatchObject({ stage: 'uploading', amounts: { uploadedBytes: '50', preparedBytes: '100' } })
        run.finish('complete'); stop()
    })
})
describe('phase denominators', () => {
    const job: ExternalJobSummary = { id: 'job', connectionId: 'a', kind: 'restore', state: 'running', phase: 'downloading', counters: 'transferred', completedBytes: '100', totalBytes: '100', completedItems: '1', startedAtMs: '0', updatedAtMs: '0' }
    it.each(['preparing-local', 'applying-local', 'awaiting-adoption'])('keeps %s indeterminate after a complete download', phase => {
        expect(externalJobFraction({ ...job, phase })).toBeNull()
    })
    it('uses fixed download totals but never a growing backup upload total', () => {
        expect(externalJobFraction(job)).toBe(1)
        expect(externalJobFraction({ ...job, kind: 'backup' })).toBeNull()
    })
})
